/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 28/07/2022
/// </summary>
[DataContractAttribute]
class METPriceDataFeedContract extends METSysOperationQueryDataContractBase implements SysOperationValidatable, SysOperationInitializable
{
    boolean                 isMainBatchTask;
    CreatedTransactionId    createdTransactionId;
    METThreadCount          threadCount;
    METBundleCount          bundleCount;
    SysGuidString           taskGuidStr;

}

Method.Source:
    /// <summary>Validate the variables</summary>
    /// <returns>The result of the validation</returns>
    public boolean validate()
    {
        boolean isValid = true;
        
        if(threadCount <= 0)
        {
            isValid = checkFailed("@MET:ThreadCountWarning");
        }

        if(bundleCount <= 0)
        {
            isValid = checkFailed("@MET:BundleSizeWarning");
        }

        return isValid;
    }

/// <summary>Initialise global variables</summary>
public void initialize()
{
    isMainBatchTask = true;
}

    /// <summary>Parm the thread count variable</summary>
    /// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
    /// <returns>The thread count</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(true)]
    public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
    {
        threadCount = _threadCount;

        return threadCount;
    }

    /// <summary>Parm the bundle count variable</summary>
    /// <param name = "_bundleCount">Number of records per bundle</param>
    /// <returns>The bundle count</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(true)]
    public METBundleCount parmBundleCount(METBundleCount _bundleCount = bundleCount)
    {
        bundleCount = _bundleCount;

        return bundleCount;
    }

    /// <summary>Parm the main task variable</summary>
    /// <param name = "_isMainBatchTask">The main task value</param>
    /// <returns>The main task value</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public Boolean parmIsMainBatchTask(Boolean _isMainBatchTask = isMainBatchTask)
    {
        isMainBatchTask = _isMainBatchTask;

        return isMainBatchTask;
    }

/// <summary>
/// Parm the task GUID variable as a string
/// </summary>
/// <param name="_taskGuidStr">The new value of the datacontract parameter taskGuid</param>
/// <returns>The current value of datacontract parameter taskGuid</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public SysGuidString parmTaskGuidStr(SysGuidString _taskGuidStr = taskGuidStr)
{
    taskGuidStr = _taskGuidStr;
    return taskGuidStr;
}

/// <summary>
/// Constuct new object. Used when process is run async from gui and not batched
/// </summary>
/// <returns>New contract object</returns>
public static METPriceDataFeedContract construct()   
{
    return new METPriceDataFeedContract();
}
